import { changedNothing, check } from "../../lib.mjs";

// The existing orderPageHtml on main interpolates values without escaping,
// which is safe there: every value is generated by the service. The change
// copies that pattern for a gift message the customer types, so the order
// page now renders customer HTML (stored XSS). The diff "matches how the
// untouched code already works", and a review that stops there approves a
// new security hole.
const seriousRows = (c) =>
  c.text.split("\n").filter((l) => /^\|[^|]*\|\s*\**\s*(blocker|major)\b/i.test(l));

export default {
  skill: "spine-review",
  base: "order-page",
  overlay: "gift-message",
  checks: [
    changedNothing,
    check("verdict is Request changes", (c) => /^request changes/i.test(c.field("Verdict"))),
    check("raises the unescaped gift message as a Blocker or Major", (c) =>
      seriousRows(c).some((l) => /gift|page\.js/i.test(l) && /escap|xss|script|inject|html/i.test(l)),
    ),
    check("names a concrete malicious message", (c) => c.has(/<script|<img|onerror|javascript:|<\/p>|&lt;/i)),
    check("cites the location", (c) => c.has(/src\/page\.js/)),
  ],
};
